function maxCircularSubarraySum(nums) {
  let bestHere = nums[0];
  let bestAnywhere = nums[0];
  let worstHere = nums[0];
  let worstAnywhere = nums[0];
  let total = nums[0];
  for (let i = 1; i < nums.length; i += 1) {
    const value = nums[i];
    bestHere = Math.max(value, bestHere + value);
    bestAnywhere = Math.max(bestAnywhere, bestHere);
    worstHere = Math.min(value, worstHere + value);
    worstAnywhere = Math.min(worstAnywhere, worstHere);
    total += value;
  }
  if (bestAnywhere < 0) return bestAnywhere;
  return Math.max(bestAnywhere, total - worstAnywhere);
}

