def max_circular_subarray_sum(nums):
    n = len(nums)
    doubled = nums + nums
    prefix = [0]
    for value in doubled:
        prefix.append(prefix[-1] + value)
    queue = []
    head = 0
    best = None
    for right in range(1, 2 * n + 1):
        entering = right - 1
        while len(queue) > head and prefix[queue[-1]] >= prefix[entering]:
            queue.pop()
        queue.append(entering)
        while queue[head] < right - n:
            head += 1
        candidate = prefix[right] - prefix[queue[head]]
        if best is None or candidate > best:
            best = candidate
    return best

